 const [u,r,b]=await Promise.all([sb.from("users").select("id,full_name,username,email,phone,is_active,branch_id,roles(name)").limit(300),sb.from("roles").select("id,name,description,is_system_role").limit(100),sb.from("branches").select("id,name").eq("is_active",true)]);
