function supplierForm(){modal("Add Supplier",`<form onsubmit="saveSupplier(event)" class=form-grid><input id=s_name placeholder="Supplier name" required><input id=s_phone placeholder="Phone"><input id=s_email placeholder="Email"><input id=s_address placeholder="Address"><input id=s_due type=number step=.01 placeholder="Opening due"><button class=primary style="grid-column:1/-1">Save Supplier</button></form>`)}
async function saveSupplier(e){e.preventDefault();const {error}=await sb.rpc("create_supplier",{p_name:$("#s_name").value,p_phone:$("#s_phone").value,p_email:$("#s_email").value,p_address:$("#s_address").value,p_opening_due:Number($("#s_due").value||0)});if(error)return alert(error.message);closeModal();suppliers()}
async function transferForm(){if(!window._warehouses)await inventory();const ps=await sb.from("products").select("id,name,sku").eq("is_active",true).limit(500);products=ps.data||[];modal("Create Stock Transfer",`<form onsubmit="saveTransfer(event)"><div class=form-grid><select id=tr_from required>${window._warehouses.map(w=>`<option value=${w.id}>From: ${w.name}</option>`).join("")}</select><select id=tr_to required>${window._warehouses.map(w=>`<option value=${w.id}>To: ${w.name}</option>`).join("")}</select><select id=tr_product required>${products.map(p=>`<option value=${p.id}>${p.name} ${p.sku||""}</option>`).join("")}</select><input id=tr_qty type=number min=.01 step=.01 placeholder="Quantity" required><input id=tr_cost type=number step=.01 placeholder="Unit cost"><input id=tr_notes placeholder="Notes"><button class=primary style="grid-column:1/-1">Create Transfer</button></div></form>`)}
async function saveTransfer(e){e.preventDefault();const items=[{product_id:$("#tr_product").value,quantity:Number($("#tr_qty").value),unit_cost:Number($("#tr_cost").value||0)}];const {error}=await sb.rpc("create_stock_transfer",{p_from_warehouse_id:$("#tr_from").value,p_to_warehouse_id:$("#tr_to").value,p_items:items,p_notes:$("#tr_notes").value});if(error)return alert(error.message);closeModal();inventory()}
async function approveTransfer(id){const {error}=await sb.rpc("approve_stock_transfer",{p_transfer_id:id});if(error)alert(error.message);else inventory()}async function receiveTransfer(id){const {error}=await sb.rpc("receive_stock_transfer",{p_transfer_id:id});if(error)alert(error.message);else inventory()}
async function adjustmentForm(){if(!window._warehouses)await inventory();const ps=await sb.from("products").select("id,name,sku").eq("is_active",true).limit(500);products=ps.data||[];modal("Stock Adjustment",`<form onsubmit="saveAdjustment(event)"><div class=form-grid><select id=ad_wh required>${window._warehouses.map(w=>`<option value=${w.id}>${w.name}</option>`).join("")}</select><select id=ad_product required>${products.map(p=>`<option value=${p.id}>${p.name} ${p.sku||""}</option>`).join("")}</select><select id=ad_type><option value=IN>Adjustment In</option><option value=OUT>Adjustment Out</option><option value=DAMAGE>Damage</option><option value=CONSUMPTION>Consumption</option></select><input id=ad_qty type=number min=.01 step=.01 placeholder="Quantity" required><input id=ad_cost type=number step=.01 placeholder="Unit cost"><input id=ad_reason placeholder="Reason"><button class=primary style="grid-column:1/-1">Post Adjustment</button></div></form>`)}
async function saveAdjustment(e){e.preventDefault();const {error}=await sb.rpc("create_stock_adjustment",{p_warehouse_id:$("#ad_wh").value,p_items:[{product_id:$("#ad_product").value,quantity:Number($("#ad_qty").value),adjustment_type:$("#ad_type").value,unit_cost:Number($("#ad_cost").value||0)}],p_reason:$("#ad_reason").value,p_notes:null});if(error)return alert(error.message);closeModal();inventory()}
async function approveMember(id,tier){const {error}=await sb.rpc("approve_customer_membership",{p_application_id:id,p_tier_id:tier});if(error)alert(error.message);else membership()}async function rejectMember(id){const reason=prompt("Rejection reason:");const {error}=await sb.rpc("reject_customer_membership",{p_application_id:id,p_reason:reason||null});if(error)alert(error.message);else membership()}
async function saleReturnForm(id){const {data,error}=await sb.from("v_invoice_details").select("sale_item_id,product_id,product_name,quantity,unit_price,line_total").eq("sale_id",id);if(error)return alert(error.message);modal("Sale Return",`<form onsubmit="saveSaleReturn(event,'${id}')"><div class=table-wrap><table class=table><tr><th>Product</th><th>Sold</th><th>Return Qty</th></tr>${(data||[]).map((x,i)=>`<tr><td>${x.product_name}</td><td>${x.quantity}</td><td><input id="sr_${i}" data-item="${x.sale_item_id}" data-product="${x.product_id}" type=number min=0 step=.01 max="${x.quantity}" value=0></td></tr>`).join("")}</table></div><input id=sr_notes placeholder="Notes" style="margin-top:10px"><button class=primary style="margin-top:10px">Post Return</button></form>`);window._returnItems=data||[]}
async function saveSaleReturn(e,id){e.preventDefault();const items=window._returnItems.map((x,i)=>({sale_item_id:x.sale_item_id,product_id:x.product_id,quantity:Number($(`#sr_${i}`).value||0)})).filter(x=>x.quantity>0);if(!items.length)return alert("Select return quantity");const {error}=await sb.rpc("create_sale_return",{p_sale_id:id,p_items:items,p_notes:$("#sr_notes").value});if(error)return alert(error.message);closeModal();salesHistory()}
async function purchaseReturnForm(id){const {data,error}=await sb.from("purchase_items").select("id,product_id,quantity,unit_cost,batch_no,expiry_date,products(name)").eq("purchase_id",id);if(error)return alert(error.message);modal("Purchase Return",`<form onsubmit="savePurchaseReturn(event,'${id}')"><div class=table-wrap><table class=table><tr><th>Product</th><th>Purchased</th><th>Return Qty</th></tr>${(data||[]).map((x,i)=>`<tr><td>${x.products?.name||x.product_id}</td><td>${x.quantity}</td><td><input id="pr_${i}" data-item="${x.id}" data-product="${x.product_id}" type=number min=0 step=.01 max="${x.quantity}" value=0></td></tr>`).join("")}</table></div><input id=pr_notes placeholder="Notes" style="margin-top:10px"><button class=primary style="margin-top:10px">Post Return</button></form>`);window._purchaseReturnItems=data||[]}
async function savePurchaseReturn(e,id){e.preventDefault();const items=window._purchaseReturnItems.map((x,i)=>({purchase_item_id:x.id,product_id:x.product_id,quantity:Number($(`#pr_${i}`).value||0)})).filter(x=>x.quantity>0);if(!items.length)return alert("Select return quantity");const {error}=await sb.rpc("create_purchase_return",{p_purchase_id:id,p_items:items,p_notes:$("#pr_notes").value});if(error)return alert(error.message);closeModal();purchases()}
async function printInvoice(id){const {data,error}=await sb.from("v_invoice_details").select("*").eq("sale_id",id);if(error||!data?.length)return alert(error?.message||"Invoice not found");const h=data[0];const rows=data.map(x=>`<tr><td>${x.product_name}</td><td>${x.quantity}</td><td>${Number(x.unit_price).toLocaleString()}</td><td>${Number(x.line_total).toLocaleString()}</td></tr>`).join("");const w=window.open("","_blank","width=800,height=900");w.document.write(`<html><head><title>${h.invoice_no}</title><style>body{font-family:Arial;padding:30px}table{width:100%;border-collapse:collapse;margin-top:20px}th,td{border-bottom:1px solid #ddd;padding:10px;text-align:left}.total{text-align:right;font-size:18px;font-weight:bold}</style></head><body><h1>CHOIX ERP</h1><h3>Invoice: ${h.invoice_no}</h3><p>${new Date(h.sale_date).toLocaleString()}<br>Customer: ${h.customer_name||"Walk-in"} ${h.customer_phone||""}</p><table><tr><th>Product</th><th>Qty</th><th>Price</th><th>Total</th></tr>${rows}</table><p class=total>Grand Total: ${Number(h.total_amount).toLocaleString()} BDT</p><p>Paid: ${Number(h.paid_amount).toLocaleString()} BDT &nbsp; Due: ${Number(h.due_amount).toLocaleString()} BDT</p><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close()}
async function pos(){
 const [pr,br,wh,pm]=await Promise.all([
  sb.from("products").select("id,name,sku,barcode,selling_price,vat_percent,purchase_price,color_group,is_active,categories(name)").eq("is_active",true).order("name").limit(1000),
  sb.from("branches").select("id,name,code").eq("is_active",true).order("name"),
  sb.from("warehouses").select("id,name,branch_id").eq("is_active",true).order("name"),
  sb.from("payment_methods").select("id,name,code").eq("is_active",true).order("name")
 ]);
 products=pr.data||[];cart=[];window._posBranches=br.data||[];window._posWarehouses=wh.data||[];window._posPaymentMethods=pm.data||[];
 const inv="POS-"+Date.now();
 $("#content").innerHTML=`
 <div class="pos-header">
  <div><div class="muted">Retail Sales Terminal</div><h2>My POS / Sale</h2><div class="muted">Invoice, customer, stock and payment — all in one screen.</div></div>
  <div class="pos-actions"><button onclick="salesHistory()">Sales / Invoice History</button><button onclick="printLastPOSInvoice()">🖨 Print Last Invoice</button></div>
 </div>
 <div class="pos-meta card">
  <div class="form-grid">
   <label>Invoice No<input id="posInvoice" value="${inv}" readonly></label>
   <label>Date<input id="posDate" type="date" value="${new Date().toISOString().slice(0,10)}"></label>
   <label>Branch<select id="posBranch" onchange="refreshPOSWarehouses()">${window._posBranches.map(x=>`<option value="${x.id}" ${x.id===profile?.branch_id?'selected':''}>${x.name}</option>`).join("")}</select></label>
   <label>Warehouse<select id="posWarehouse"></select></label>
  </div>
 </div>
 <div class="pos-layout">
  <div class="pos-main">
   <div class="card">
    <div class="section-head"><div><h3>Customer & Membership</h3><div class="muted">Phone works as Membership ID.</div></div><button onclick="newPOSCustomer()">+ New Customer</button></div>
    <div class="form-grid">
      <input id="posCustomerPhone" placeholder="Customer Phone / Membership ID" onblur="lookupPOSCustomer()" onkeydown="if(event.key==='Enter'){event.preventDefault();lookupPOSCustomer()}">
      <input id="posCustomerName" placeholder="Customer Name">
      <input id="posCustomerAddress" placeholder="Address">
      <input id="posCustomerEmail" type="email" placeholder="Email">
    </div>
    <div id="posCustomerInfo" class="member-banner muted">Walk-in customer</div>
   </div>
   <div class="card">
    <div class="section-head"><div><h3>Products</h3><div class="muted">Search by product, SKU or scan barcode.</div></div></div>
    <div class="pos-search"><input id="posSearch" placeholder="Search product / barcode / SKU" oninput="renderProducts()" onkeydown="scanPOSBarcode(event)" autofocus><button onclick="scanPOSBarcode({key:'Enter',preventDefault:()=>{}})">Add Barcode</button></div>
    <div id="productList" class="product-list"></div>
   </div>
   <div class="card">
    <div class="section-head"><h3>Sale Items</h3><span class="pill" id="posItemCount">0 Items</span></div>
    <div id="cart" class="pos-cart"></div>
   </div>
  </div>
  <div class="pos-side">
   <div class="card sticky-pos">
    <h3>Payment & Summary</h3>
    <div id="posSummary"></div>
    <div class="pos-pay-grid">
      <label>Discount<input id="posDiscount" type="number" min="0" step=".01" value="0" oninput="renderCart()"></label>
      
    </div>
    <label>Payment Method<select id="posPaymentMethod">${window._posPaymentMethods.map(x=>`<option value="${x.id}">${x.name}</option>`).join("")}</select></label>
    <label>Paid Amount<input id="posPaid" type="number" min="0" step=".01" value="0" oninput="renderCart()"></label>
    <label>Notes<textarea id="posNotes" rows="3" placeholder="Sale notes"></textarea></label>
    <div id="posMsg" class="msg"></div>
    <button class="primary pos-complete" onclick="checkout()">✓ Complete Sale & Print Invoice</button>
    <button class="secondary pos-clear" onclick="clearPOS()">Clear / New Sale</button>
   </div>
  </div>
 </div>`;
 refreshPOSWarehouses();renderProducts();renderCart();
}
function refreshPOSWarehouses(){const b=$("#posBranch")?.value;if(!b)return;$("#posWarehouse").innerHTML=(window._posWarehouses||[]).filter(x=>x.branch_id===b).map(x=>`<option value="${x.id}">${x.name}</option>`).join("")}
function scanPOSBarcode(e){if(e.key!=="Enter")return;e.preventDefault();const q=$("#posSearch").value.trim().toLowerCase();if(!q)return;const p=products.find(x=>String(x.barcode||'').toLowerCase()===q||String(x.sku||'').toLowerCase()===q);if(p){addCart(p.id);$("#posSearch").select();toast(`${p.name} added`)}else{$("#posMsg").textContent="Product barcode / SKU not found."}}
function renderProducts(){const q=($("#posSearch")?.value||"").toLowerCase();const list=products.filter(p=>(p.name+" "+(p.sku||"")+" "+(p.barcode||"")+" "+(p.color_group||"")).toLowerCase().includes(q)).slice(0,80);$("#productList").innerHTML=list.map(p=>`<button class="product-btn pos-product" onclick="addCart('${p.id}')"><b>${esc(p.name)}</b><span class="muted">${esc(p.categories?.name||p.color_group||'')} · ${esc(p.sku||'')}</span><span class="muted">Barcode: ${esc(p.barcode||'')}</span><strong>৳ ${Number(p.selling_price||0).toLocaleString()}</strong></button>`).join("")||`<div class="muted">No matching products.</div>`}
function addCart(id){const p=products.find(x=>x.id===id);if(!p)return;const x=cart.find(x=>x.id===id);if(x)x.qty++;else cart.push({id:p.id,name:p.name,sku:p.sku,barcode:p.barcode,category:p.categories?.name||"",price:Number(p.selling_price||0),vat:Number(p.vat_percent||0),qty:1,discountPct:0});renderCart()}
function changeCartQty(i,v){const q=Math.max(0,Number(v||0));if(q===0)cart.splice(i,1);else cart[i].qty=q;renderCart()}
function changeCartDiscount(i,v){cart[i].discountPct=Math.max(0,Number(v||0));renderCart()}
function renderCart(){
 const sub=cart.reduce((s,x)=>s+(x.qty*x.price),0),lineDisc=cart.reduce((s,x)=>s+(x.qty*x.price*Number(x.discountPct||0)/100),0),disc=Math.max(0,Number($("#posDiscount")?.value||0))+lineDisc,total=Math.max(0,sub-disc),paid=Math.max(0,Number($("#posPaid")?.value||0)),due=Math.max(0,total-paid),change=Math.max(0,paid-total);
 $("#posItemCount")&&($("#posItemCount").textContent=cart.reduce((s,x)=>s+x.qty,0)+" Items");
 $("#cart").innerHTML=cart.length?`<div class="pos-table"><div class="pos-row pos-head"><span>Product</span><span>Qty</span><span>Price</span><span>Disc.</span><span>Total</span><span></span></div>${cart.map((x,i)=>`<div class="pos-row"><span><b>${esc(x.name)}</b><small>${esc(x.sku||'')} · ${esc(x.barcode||'')}</small></span><input type=number min=0 step=.01 value="${x.qty}" onchange="changeCartQty(${i},this.value)"><span>৳ ${x.price.toLocaleString()}</span><input type=number min=0 step=.01 value="${x.discountPct||0}" onchange="changeCartDiscount(${i},this.value)"><b>৳ ${(Math.max(0,x.qty*x.price-(x.qty*x.price*Number(x.discountPct||0)/100))).toLocaleString()}</b><button onclick="changeCartQty(${i},0)">×</button></div>`).join("")}</div>`:`<div class="empty-pos">No items added. Search or scan a barcode to start the sale.</div>`;
 $("#posSummary").innerHTML=`<div class="summary-line"><span>Subtotal</span><b>৳ ${sub.toLocaleString()}</b></div><div class="summary-line"><span>Discount</span><b>− ৳ ${disc.toLocaleString()}</b></div><div class="summary-total"><span>Grand Total</span><b>৳ ${total.toLocaleString()}</b></div><div class="summary-line"><span>Paid</span><b>৳ ${paid.toLocaleString()}</b></div><div class="summary-line"><span>Due</span><b>৳ ${due.toLocaleString()}</b></div>${change?`<div class="summary-line"><span>Change</span><b>৳ ${change.toLocaleString()}</b></div>`:''}`;
}
async function lookupPOSCustomer(){const phone=$("#posCustomerPhone")?.value.trim();if(!phone){$("#posCustomerInfo").textContent="Walk-in customer";return}const {data:c}=await sb.from("customers").select("id,name,phone,email,address").eq("phone",phone).limit(1);const customer=c?.[0];if(customer){$("#posCustomerName").value=customer.name||'';$("#posCustomerAddress").value=customer.address||'';$("#posCustomerEmail").value=customer.email||'';window._posCustomerId=customer.id;const {data:m}=await sb.rpc("lookup_membership_by_phone",{p_phone:phone});const mm=m?.[0];$("#posCustomerInfo").innerHTML=mm?`✓ Member: <b>${esc(mm.customer_name)}</b> · ${esc(mm.tier_name||'Member')} · ${mm.points_balance} points`:`Customer found · Not an active member`}
else{window._posCustomerId=null;$("#posCustomerInfo").textContent="New customer — name/address can be saved with the sale."}}
function newPOSCustomer(){["#posCustomerPhone","#posCustomerName","#posCustomerAddress","#posCustomerEmail"].forEach(s=>{if($(s))$(s).value=''});window._posCustomerId=null;$("#posCustomerInfo").textContent="New / Walk-in customer";$("#posCustomerPhone").focus()}
async function ensurePOSCustomer(){let id=window._posCustomerId||null;const name=$("#posCustomerName").value.trim(),phone=$("#posCustomerPhone").value.trim(),email=$("#posCustomerEmail").value.trim(),address=$("#posCustomerAddress").value.trim();if(id||(!name&&!phone))return id;if(phone){const {data:c}=await sb.from("customers").select("id").eq("phone",phone).limit(1);if(c?.[0]?.id)return c[0].id}if(!name)return null;const {data,error}=await sb.rpc("create_customer",{p_name:name,p_phone:phone||null,p_email:email||null,p_address:address||null,p_credit_limit:0,p_opening_due:0});if(error)throw error;return data?.id||data}
async function checkout(){
 if(!cart.length)return $("#posMsg").textContent="Add at least one product.";
 const branch=$("#posBranch").value,warehouse=$("#posWarehouse").value,pm=$("#posPaymentMethod").value;if(!branch||!warehouse)return $("#posMsg").textContent="Select branch and warehouse.";if(!pm)return $("#posMsg").textContent="Select a payment method.";
 const sub=cart.reduce((s,x)=>s+x.qty*x.price,0),lineDisc=cart.reduce((s,x)=>s+(x.qty*x.price*Number(x.discountPct||0)/100),0),discount=Math.max(0,Number($("#posDiscount").value||0))+lineDisc,total=Math.max(0,sub-discount),paid=Math.max(0,Number($("#posPaid").value||0));
 if(paid>total)return $("#posMsg").textContent="Paid amount cannot be greater than Grand Total.";
 try{const customer=await ensurePOSCustomer();const items=cart.map(x=>({product_id:x.id,quantity:x.qty,unit_price:x.price,discount_amount:Number(x.qty*x.price*Number(x.discountPct||0)/100)}));const payments=paid>0?[{payment_method_id:pm,amount:paid}]:[];const {data,error}=await sb.rpc("create_pos_sale",{p_branch_id:branch,p_warehouse_id:warehouse,p_invoice_no:$("#posInvoice").value,p_customer_id:customer,p_items:items,p_payments:payments,p_discount_amount:Math.max(0,Number($("#posDiscount").value||0)),p_notes:$("#posNotes").value||null});if(error)throw error;window._lastPOSInvoiceId=typeof data==='string'?data:data?.id||data?.sale_id;toast("Sale completed successfully");await printInvoice(window._lastPOSInvoiceId);clearPOS(false)}catch(err){$("#posMsg").textContent=err.message||String(err)}}
function clearPOS(show=true){cart=[];window._posCustomerId=null;$("#posInvoice")&&($("#posInvoice").value="POS-"+Date.now());["#posCustomerPhone","#posCustomerName","#posCustomerAddress","#posCustomerEmail","#posNotes"].forEach(s=>{if($(s))$(s).value=''});if($("#posDiscount"))$("#posDiscount").value=0;if($("#posPaid"))$("#posPaid").value=0;if(show)toast("New sale ready");renderCart()}
function printLastPOSInvoice(){if(window._lastPOSInvoiceId)printInvoice(window._lastPOSInvoiceId);else toast("No completed sale yet","error")}

function renderProducts(){const q=($("#posSearch")?.value||"").toLowerCase();$("#productList").innerHTML=products.filter(p=>(p.name+" "+(p.sku||"")+" "+(p.barcode||"")).toLowerCase().includes(q)).map(p=>`<button class=product-btn onclick="addCart('${p.id}')"><b>${p.name}</b><br><span class=muted>${p.sku||""}</span><br>${Number(p.selling_price).toLocaleString()} BDT</button>`).join("")}
function addCart(id){const p=products.find(x=>x.id===id),x=cart.find(x=>x.id===id);if(x)x.qty++;else cart.push({id:p.id,name:p.name,price:Number(p.selling_price),qty:1});renderCart()}function renderCart(){let t=0;$("#cart").innerHTML=cart.map(x=>{let l=x.qty*x.price;t+=l;return `<div class=cart-row><span>${x.name} × ${x.qty}</span><b>${l.toLocaleString()}</b></div>`}).join("");$("#cartTotal").textContent=t.toLocaleString()+" BDT"}
async function lookupMember(){const phone=$("#memberPhone").value.trim();if(!phone)return;const {data,error}=await sb.rpc("lookup_membership_by_phone",{p_phone:phone});if(error)return $("#memberInfo").textContent=error.message;const m=data?.[0];$("#memberInfo").innerHTML=m?`✓ ${m.customer_name} · ${m.tier_name||"Member"} · ${m.points_balance} points`:`No active membership found`}
async function purchaseEntry(){
 const [br,wh,su,ps,pa]=await Promise.all([sb.from("branches").select("id,name").eq("is_active",true),sb.from("warehouses").select("id,name,branch_id").eq("is_active",true),sb.from("suppliers").select("id,name,phone").eq("is_active",true),sb.from("products").select("id,name,sku,purchase_price,vat_percent").eq("is_active",true).limit(500),sb.from("payment_accounts").select("id,name,account_kind").eq("is_active",true)]);
 window._purchaseData={branches:br.data||[],warehouses:wh.data||[],suppliers:su.data||[],products:ps.data||[],paymentAccounts:pa.data||[]};window._purchaseRows=[{product_id:"",quantity:1,unit_cost:0,discount_amount:0,vat_amount:0,batch_no:"",expiry_date:""}];
 modal("Purchase Entry / Goods Receive",`<form onsubmit="savePurchaseEntry(event)"><div class=form-grid><select id=pe_branch required onchange="refreshPurchaseWarehouses()">${window._purchaseData.branches.map(x=>`<option value=${x.id}>${x.name}</option>`).join("")}</select><select id=pe_wh required></select><select id=pe_supplier required>${window._purchaseData.suppliers.map(x=>`<option value=${x.id}>${x.name} ${x.phone||""}</option>`).join("")}</select><input id=pe_invoice placeholder="Purchase Invoice No" required><input id=pe_supplier_invoice placeholder="Supplier Invoice / GRN Ref"><select id=pe_pay>${window._purchaseData.paymentAccounts.map(x=>`<option value=${x.id}>${x.name}</option>`).join("")}</select><input id=pe_paid type=number min=0 step=.01 value=0 placeholder="Paid Amount"><input id=pe_notes placeholder="Notes"></div><div class=section-head style="margin-top:16px"><h3>Items</h3><button type=button onclick="addPurchaseRow()">+ Add Item</button></div><div id=pe_rows></div><button class=primary style="margin-top:14px">Post Purchase & Receive Stock</button></form>`);refreshPurchaseWarehouses();renderPurchaseRows();}
function refreshPurchaseWarehouses(){const b=$("#pe_branch")?.value;if(!b)return;$("#pe_wh").innerHTML=(window._purchaseData.warehouses||[]).filter(x=>x.branch_id===b).map(x=>`<option value=${x.id}>${x.name}</option>`).join("");}
function addPurchaseRow(){window._purchaseRows.push({product_id:"",quantity:1,unit_cost:0,discount_amount:0,vat_amount:0,batch_no:"",expiry_date:""});renderPurchaseRows();}
function renderPurchaseRows(){const ps=window._purchaseData.products||[];$("#pe_rows").innerHTML=window._purchaseRows.map((r,i)=>`<div class="purchase-row"><select onchange="purchaseRowChange(${i},'product_id',this.value)"><option value="">Product</option>${ps.map(p=>`<option value=${p.id} ${p.id===r.product_id?'selected':''}>${p.name} ${p.sku||''}</option>`).join('')}</select><input type=number min=.01 step=.01 value=${r.quantity} onchange="purchaseRowChange(${i},'quantity',this.value)" placeholder=Qty><input type=number min=0 step=.01 value=${r.unit_cost} onchange="purchaseRowChange(${i},'unit_cost',this.value)" placeholder=Cost><input type=number min=0 step=.01 value=${r.discount_amount} onchange="purchaseRowChange(${i},'discount_amount',this.value)" placeholder=Discount><input type=number min=0 step=.01 value=${r.vat_amount} onchange="purchaseRowChange(${i},'vat_amount',this.value)" placeholder=VAT><input value="${r.batch_no||''}" onchange="purchaseRowChange(${i},'batch_no',this.value)" placeholder=Batch><input type=date value="${r.expiry_date||''}" onchange="purchaseRowChange(${i},'expiry_date',this.value)"><button type=button onclick="removePurchaseRow(${i})">×</button></div>`).join("");}
function purchaseRowChange(i,k,v){window._purchaseRows[i][k]=['quantity','unit_cost','discount_amount','vat_amount'].includes(k)?Number(v||0):v;}
function removePurchaseRow(i){if(window._purchaseRows.length===1)return;window._purchaseRows.splice(i,1);renderPurchaseRows();}
async function savePurchaseEntry(e){e.preventDefault();const items=window._purchaseRows.filter(r=>r.product_id).map(r=>({...r}));if(!items.length)return alert("Add at least one product");const {data,error}=await sb.rpc("create_purchase_entry",{p_branch_id:$("#pe_branch").value,p_warehouse_id:$("#pe_wh").value,p_supplier_id:$("#pe_supplier").value,p_invoice_no:$("#pe_invoice").value,p_supplier_invoice_no:$("#pe_supplier_invoice").value||null,p_items:items,p_paid_amount:Number($("#pe_paid").value||0),p_payment_account_id:$("#pe_pay").value||null,p_notes:$("#pe_notes").value||null});if(error)return alert(error.message);const purchaseId=typeof data==='string'?data:data?.id||data?.purchase_id;closeModal();purchases();toast('Purchase received. Stock updated and barcode labels are ready.');if(purchaseId)setTimeout(()=>printPurchaseLabels(purchaseId),250)}
async function customerDue(){const {data,error}=await sb.from("v_customer_due_summary").select("customer_id,customer_code,name,phone,opening_due,due_amount").gt("due_amount",0).order("due_amount",{ascending:false}).limit(500);if(error)return tablePage("Customer Due",data,error);const rows=(data||[]).map(r=>({...r,action:`<button onclick="customerPaymentForm('${r.customer_id}','${String(r.name).replace(/'/g,"\\'")}','${r.due_amount}')">Collect</button>`}));tablePage("Customer Due / Payment",rows,null,false);}
async function supplierDue(){const {data,error}=await sb.from("v_supplier_due_summary").select("supplier_id,supplier_code,name,phone,opening_due,due_amount").gt("due_amount",0).order("due_amount",{ascending:false}).limit(500);if(error)return tablePage("Supplier Due",data,error);const rows=(data||[]).map(r=>({...r,action:`<button onclick="supplierPaymentForm('${r.supplier_id}','${String(r.name).replace(/'/g,"\\'")}','${r.due_amount}')">Pay</button>`}));tablePage("Supplier Due / Payment",rows,null,false);}
async function customerPaymentForm(id,name,due){const {data:pa}=await sb.from("payment_accounts").select("id,name").eq("is_active",true);modal("Collect Customer Due",`<form onsubmit="saveCustomerPayment(event,'${id}')"><p><b>${name}</b> · Outstanding: ${Number(due).toLocaleString()} BDT</p><div class=form-grid><input id=cp_amount type=number min=.01 max=${due} step=.01 placeholder="Amount" required><select id=cp_account><option value="">Payment account</option>${(pa||[]).map(x=>`<option value=${x.id}>${x.name}</option>`).join("")}</select><input id=cp_ref placeholder="Reference No"><input id=cp_notes placeholder="Notes"></div><button class=primary>Collect Payment</button></form>`)}
async function saveCustomerPayment(e,id){e.preventDefault();const {error}=await sb.rpc("create_customer_payment",{p_customer_id:id,p_amount:Number($("#cp_amount").value),p_payment_account_id:$("#cp_account").value||null,p_branch_id:profile?.branch_id||null,p_reference_no:$("#cp_ref").value||null,p_notes:$("#cp_notes").value||null});if(error)return alert(error.message);closeModal();customerDue();}
async function supplierPaymentForm(id,name,due){const {data:pa}=await sb.from("payment_accounts").select("id,name").eq("is_active",true);modal("Pay Supplier Due",`<form onsubmit="saveSupplierPayment(event,'${id}')"><p><b>${name}</b> · Outstanding: ${Number(due).toLocaleString()} BDT</p><div class=form-grid><input id=sp_amount type=number min=.01 max=${due} step=.01 placeholder="Amount" required><select id=sp_account><option value="">Payment account</option>${(pa||[]).map(x=>`<option value=${x.id}>${x.name}</option>`).join("")}</select><input id=sp_ref placeholder="Reference No"><input id=sp_notes placeholder="Notes"></div><button class=primary>Pay Supplier</button></form>`)}
async function saveSupplierPayment(e,id){e.preventDefault();const {error}=await sb.rpc("create_supplier_payment",{p_supplier_id:id,p_amount:Number($("#sp_amount").value),p_payment_account_id:$("#sp_account").value||null,p_branch_id:profile?.branch_id||null,p_reference_no:$("#sp_ref").value||null,p_notes:$("#sp_notes").value||null});if(error)return alert(error.message);closeModal();supplierDue();}
async function journalForm(){const {data:a}=await sb.from("accounts").select("id,account_code,account_name").eq("is_active",true).limit(500);window._accounts=a||[];window._journalRows=[{account_id:"",debit:0,credit:0,description:""},{account_id:"",debit:0,credit:0,description:""}];modal("New Journal Entry",`<form onsubmit="saveJournal(event)"><div class=form-grid><input id=j_no placeholder="Journal No" value="JV-${Date.now()}" required><input id=j_desc placeholder="Description"><input id=j_ref_type placeholder="Reference Type"><input id=j_ref_id placeholder="Reference ID"></div><div class=section-head style="margin-top:16px"><h3>Journal Lines</h3><button type=button onclick="addJournalRow()">+ Line</button></div><div id=j_rows></div><button class=primary>Post Journal</button></form>`);renderJournalRows();}
function addJournalRow(){window._journalRows.push({account_id:"",debit:0,credit:0,description:""});renderJournalRows();}
function renderJournalRows(){const a=window._accounts||[];$("#j_rows").innerHTML=window._journalRows.map((r,i)=>`<div class="journal-row"><select onchange="jChange(${i},'account_id',this.value)"><option value="">Account</option>${a.map(x=>`<option value=${x.id} ${x.id===r.account_id?'selected':''}>${x.account_code} - ${x.account_name}</option>`).join('')}</select><input type=number min=0 step=.01 value=${r.debit} onchange="jChange(${i},'debit',this.value)" placeholder=Debit><input type=number min=0 step=.01 value=${r.credit} onchange="jChange(${i},'credit',this.value)" placeholder=Credit><input value="${r.description||''}" onchange="jChange(${i},'description',this.value)" placeholder=Description></div>`).join("");}
function jChange(i,k,v){window._journalRows[i][k]=['debit','credit'].includes(k)?Number(v||0):v;}
async function saveJournal(e){e.preventDefault();const {data,error}=await sb.rpc("create_journal_entry",{p_branch_id:profile?.branch_id||null,p_journal_no:$("#j_no").value,p_description:$("#j_desc").value||null,p_lines:window._journalRows,p_reference_type:$("#j_ref_type").value||null,p_reference_id:$("#j_ref_id").value||null});if(error)return alert(error.message);closeModal();accountTransactions();alert("Journal posted: "+data);}
/* Barcode + label printing */
const EAN_L={0:'0001101',1:'0011001',2:'0010011',3:'0111101',4:'0100011',5:'0110001',6:'0101111',7:'0111011',8:'0110111',9:'0001011'};
const EAN_G={0:'0100111',1:'0110011',2:'0011011',3:'0100001',4:'0011101',5:'0111001',6:'0000101',7:'0010001',8:'0001001',9:'0010111'};
const EAN_R={0:'1110010',1:'1100110',2:'1101100',3:'1000010',4:'1011100',5:'1001110',6:'1010000',7:'1000100',8:'1001000',9:'1110100'};
const EAN_PARITY={0:'LLLLLL',1:'LLGLGG',2:'LLGGLG',3:'LLGGGL',4:'LGLLGG',5:'LGGLLG',6:'LGGGLL',7:'LGLGLG',8:'LGLGGL',9:'LGGLGL'};
function ean13Svg(raw){let d=String(raw||'').replace(/\D/g,'');if(d.length===12){let sum=0;for(let i=0;i<12;i++)sum+=Number(d[i])*(i%2?3:1);d+=String((10-sum%10)%10)}if(d.length!==13)return `<div class=barcode-fallback>${esc(raw||'')}</div>`;const first=Number(d[0]),par=EAN_PARITY[first];let bits='101';for(let i=0;i<6;i++)bits+=par[i]==='L'?EAN_L[d[i+1]]:EAN_G[d[i+1]];bits+='01010';for(let i=7;i<13;i++)bits+=EAN_R[d[i]];bits+='101';let rects='',x=8;for(const bit of bits){if(bit==='1')rects+=`<rect x="${x}" y="2" width="1" height="48"/>`;x++}return `<svg class=barcode-svg viewBox="0 0 ${x+8} 62" preserveAspectRatio="none" aria-label="Barcode"><g shape-rendering="crispEdges">${rects}</g><text x="${x/2}" y="60" text-anchor="middle" font-size="8" font-family="Arial">${d}</text></svg>`}
function labelCard(p){return `<div class=print-label><div class=label-brand>CHOIX</div><div class=label-name>${esc(p.name)}</div><div class=label-meta>${esc(p.color_group||'')} ${p.sku?`· ${esc(p.sku)}`:''}</div>${ean13Svg(p.barcode)}<div class=label-price>৳ ${Number(p.selling_price||0).toLocaleString()}</div></div>`}
function openPrintDialog(products,title='Barcode Labels'){
 const list=(products||[]).filter(Boolean);if(!list.length)return toast('No products selected','error');
 modal(title,`<div class=form-grid><label>Paper / Label Size<select id=print_size><option value="a4">A4 Sheet (30 labels)</option><option value="58">58mm × 30mm</option><option value="40">40mm × 25mm</option></select></label><label>Copies per product<input id=print_copies type=number min=1 max=500 value=1></label></div><p class=muted>For received quantity printing, choose the purchase option; it will use received quantity automatically.</p><div class=tabs><button class=primary onclick="runLabelPrint()">🖨 Print Labels</button><button onclick="closeModal()">Cancel</button></div><div class=card style="margin-top:12px">${list.map(p=>`<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid #eee"><span>${esc(p.name)} · ${esc(p.barcode||'')}</span><b>৳ ${Number(p.selling_price||0).toLocaleString()}</b></div>`).join('')}</div>`);window._labelProducts=list}
function runLabelPrint(){const size=$('#print_size').value,copies=Math.max(1,Number($('#print_copies').value||1)),items=[];for(const p of (window._labelProducts||[]))for(let i=0;i<copies;i++)items.push(p);printLabelsWindow(items,size)}
function printLabelsWindow(items,size='a4'){
 const win=window.open('','_blank','width=1000,height=800');if(!win)return alert('Please allow pop-ups for CHOIX ERP to print labels.');
 const pageClass=size==='a4'?'a4':size==='58'?'label58':'label40';win.document.write(`<!doctype html><html><head><title>CHOIX Barcode Labels</title><style>@page{size:${size==='a4'?'A4':size==='58'?'58mm 30mm':'40mm 25mm'};margin:${size==='a4'?'8mm':'0'}}*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif}.sheet{display:grid;grid-template-columns:${size==='a4'?'repeat(3,1fr)': '1fr'};gap:${size==='a4'?'5mm':'0'};align-content:start}.print-label{width:${size==='a4'?'58mm':size==='58'?'58mm':'40mm'};height:${size==='a4'?'30mm':size==='58'?'30mm':'25mm'};padding:2mm;text-align:center;overflow:hidden;border:1px dashed #bbb}.label-brand{font-weight:800;font-size:9px;letter-spacing:1px}.label-name{font-weight:700;font-size:${size==='40'?'7px':'8px'};white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:1px}.label-meta{font-size:6px;height:8px;overflow:hidden}.barcode-svg{width:90%;height:${size==='40'?'11mm':'13mm'};display:block;margin:0 auto}.label-price{font-size:${size==='40'?'9px':'11px'};font-weight:800}.barcode-fallback{font-size:8px;font-weight:700;margin:5px}.sheet{width:100%}@media print{.print-label{break-inside:avoid}} </style></head><body><div class="sheet">${items.map(labelCard).join('')}</div><script>window.onload=()=>setTimeout(()=>window.print(),300)<\/script></body></html>`);win.document.close()}
async function printProductLabels(id){const {data,error}=await sb.from('products').select('id,name,sku,barcode,selling_price,color_group').eq('id',id).single();if(error)return toast(error.message,'error');openPrintDialog([data],`Print Labels · ${data.name}`)}
async function printAllProductLabels(){const {data,error}=await sb.from('products').select('id,name,sku,barcode,selling_price,color_group').eq('is_active',true).order('name').limit(500);if(error)return toast(error.message,'error');openPrintDialog(data,'Print Product Labels')}
async function printPurchaseLabels(purchaseId){const {data,error}=await sb.from('purchase_items').select('quantity,product_id,products(id,name,sku,barcode,selling_price,color_group)').eq('purchase_id',purchaseId);if(error)return toast(error.message,'error');const items=[];for(const r of (data||[])){const p=r.products;if(!p)continue;const n=Math.min(500,Math.max(1,Math.round(Number(r.quantity||1))));for(let i=0;i<n;i++)items.push(p)}if(!items.length)return toast('No received products found','error');openPrintDialog(items,'Received Goods · Barcode Labels')}

init();

/* CHOIX ERP v7 UX + reporting layer */
function toast(message,type='success'){let t=document.createElement('div');t.className='toast '+type;t.textContent=message;document.body.appendChild(t);setTimeout(()=>t.classList.add('show'),10);setTimeout(()=>{t.classList.remove('show');setTimeout(()=>t.remove(),250)},2800)}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
async function advancedReports(){
 const from=new Date(Date.now()-29*86400000).toISOString().slice(0,10),to=new Date().toISOString().slice(0,10);
 await advancedReportsRange(from,to);
}
async function advancedReportsRange(from,to){
 const {data,error}=await sb.rpc('get_erp_advanced_dashboard',{p_from:from,p_to:to});
 if(error){$('#content').innerHTML=`<div class=card error>${esc(error.message)}</div>`;return}
 const x=data||{}, money=v=>Number(v||0).toLocaleString()+' BDT';
 $('#content').innerHTML=`<div class="section-head"><div><h2>Advanced Dashboard</h2><div class="muted">Financial and operational summary</div></div><div class="report-filter"><label>From <input id="ar_from" type="date" value="${from}"></label><label>To <input id="ar_to" type="date" value="${to}"></label><button class="primary" onclick="advancedReportsRange($('#ar_from').value,$('#ar_to').value)">Apply</button></div></div>
 <div class="metric-grid">${stat('Net Sales',money(x.net_sales))}${stat('Purchases',money(x.purchases))}${stat('Expenses',money(x.expenses))}${stat('Stock Value',money(x.stock_value))}${stat('Sales Returns',money(x.sales_returns))}${stat('Purchase Returns',money(x.purchase_returns))}${stat('Customer Due',money(x.customer_due))}${stat('Supplier Due',money(x.supplier_due))}</div>
 <div class="grid2"><div class="card"><h3>Period Summary</h3>${renderTable([x],null)}</div><div class="card"><h3>Accounting</h3><div class="tabs"><button onclick="trialBalance()">Trial Balance</button><button onclick="profitLoss()">Profit & Loss</button><button onclick="backfillJournals()">Backfill Journals</button></div><p class="muted">Automatic journals are created from mapped transactions. Backfill is for older posted transactions.</p></div></div>`;
}
async function trialBalance(){const {data,error}=await sb.from('v_trial_balance').select('account_code,account_name,account_type,total_debit,total_credit,balance').order('account_code').limit(500);tablePage('Trial Balance',data,error)}
async function profitLoss(){const {data,error}=await sb.from('v_profit_loss_summary').select('account_type,account_code,account_name,net_balance').order('account_type').order('account_code').limit(500);tablePage('Profit & Loss Summary',data,error)}
async function backfillJournals(){if(!confirm('Create missing automatic journals for existing posted sales and purchases?'))return;const {data,error}=await sb.rpc('backfill_automatic_journals');if(error)return toast(error.message,'error');toast(`Backfill processed ${data?.processed||0} transaction(s)`);advancedReports()}
async function reports(){const {data,error}=await sb.from('v_daily_sales_summary').select('*').order('sale_date',{ascending:false}).limit(365);if(error)return tablePage('Sales Reports',data,error);$('#content').innerHTML=`<div class="section-head"><div><h2>Sales Reports</h2><div class="muted">Daily posted sales</div></div><button class="primary" onclick="advancedReports()">Advanced Dashboard</button></div>${renderTable(data,null)}`}
async function customerLedger(){const {data,error}=await sb.from('v_customer_ledger').select('customer_id,name,phone,transaction_type,reference_no,transaction_date,debit,credit,description').order('transaction_date',{ascending:false}).limit(1000);if(error)return tablePage('Customer Ledger',data,error);tablePage('Customer Ledger',data,null);}
async function supplierLedger(){const {data,error}=await sb.from('v_supplier_ledger').select('supplier_id,name,phone,transaction_type,reference_no,transaction_date,debit,credit,description').order('transaction_date',{ascending:false}).limit(1000);if(error)return tablePage('Supplier Ledger',data,error);tablePage('Supplier Ledger',data,null);}
